"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["80852"],{79222(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.item_formulario.impedimento_sem_o_proprio_campo","status":422,"titulo":"Cada cl\xe1usula do impedimento cita a resposta do pr\xf3prio campo"},"descricao":{"codigo":"uniplus.item_formulario.impedimento_sem_o_proprio_campo","requisitos":[],"oQueAconteceu":["O impedimento barra a inscri\xe7\xe3o por causa da resposta do campo, que pode ser combinada com respostas anteriores. Uma cl\xe1usula de `impedimento.quando` n\xe3o tem nenhuma condi\xe7\xe3o sobre o fato do pr\xf3prio item. A mensagem \xe9 \\"Cada cl\xe1usula do impedimento cita a resposta do pr\xf3prio campo; o bloqueio s\xf3 por resposta anterior \xe9 da exibi\xe7\xe3o.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `itens[i].impedimento.quando` ou, no campo de um grupo, `grupos[g].subitens[j].impedimento.quando`; nos modelos de formul\xe1rio come\xe7a por `conteudo.`. \xc9 uma entrada por item, e nada \xe9 gravado. No campo de um grupo repet\xedvel a causa \xe9 a mesma e vem no caminho do campo; como o campo de grupo n\xe3o admite impedimento, ele \xe9 recusado tamb\xe9m como [campo de grupo com impedimento](/erros/uniplus.grupo_formulario.campo_com_impedimento), na confer\xeancia da forma do grupo.","Na grava\xe7\xe3o dos itens do formul\xe1rio, esta recusa s\xf3 sai para o item cujo fato existe, \xe9 colet\xe1vel e combina com o tipo de campo: o item com fato [desconhecido](/erros/uniplus.item_formulario.fato_desconhecido), [n\xe3o colet\xe1vel](/erros/uniplus.item_formulario.fato_nao_coletavel) ou com tipo de campo [incoerente](/erros/uniplus.item_formulario.tipo_de_campo_incoerente_com_dominio) \xe9 recusado por essa causa, e o resto da forma dele s\xf3 \xe9 conferido depois que ela for corrigida. Nos modelos, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Inclua em cada cl\xe1usula do impedimento uma condi\xe7\xe3o sobre o fato que o item coleta, combinada, se for o caso, com condi\xe7\xf5es sobre respostas anteriores. Para esconder o campo conforme respostas anteriores, use a exibi\xe7\xe3o, e n\xe3o o impedimento."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Item formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);